import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { getFeaturedProducts, getProductCategories } from '../services/api';
import { isAuthenticated } from '../util/auth';
import ProductCard from '../components/ProductCard';
import { useTheme } from '../context/ThemeContext';

const Home = () => {
  const [featuredProducts, setFeaturedProducts] = useState([]);
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true);
  const [currentSlide, setCurrentSlide] = useState(0);
  const { isDarkMode } = useTheme();

  useEffect(() => {
    fetchData();
    
    // Auto-rotate slides
    const interval = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % 3);
    }, 4000);
    
    return () => clearInterval(interval);
  }, []);

  const fetchData = async () => {
    try {
      setLoading(true);
      const [featuredRes, categoriesRes] = await Promise.all([
        getFeaturedProducts(),
        getProductCategories()
      ]);
      setFeaturedProducts(featuredRes.data);
      setCategories(categoriesRes.data);
    } catch (error) {
      console.error('Error fetching data:', error);
} finally {
      setLoading(false);
    }
  };

  const userAuthenticated = isAuthenticated();

  return (
    <div className="fade-in">
      {/* Animated Hero Section */}
      <section className="relative min-h-screen flex items-center justify-center overflow-hidden rounded-2xl mb-12">
        {/* Animated Background */}
        <div className="absolute inset-0 bg-gradient-to-br from-blue-600 via-purple-600 to-pink-600">
          <div className="absolute inset-0 bg-black/20"></div>
          
          {/* Milk Bottle Pouring Animation */}
          <div className="absolute inset-0">
            {/* Main Milk Bottle */}
            <div className="absolute top-12 left-1/2 transform -translate-x-1/2 z-20">
              <div className="relative">
                {/* Bottle Shadow */}
                <div className="absolute -bottom-2 left-1/2 transform -translate-x-1/2 w-20 h-4 bg-black/20 rounded-full blur-md"></div>
                
                {/* Bottle Container */}
                <div className="w-20 h-28 bg-gradient-to-b from-blue-500 via-blue-600 to-blue-700 rounded-t-2xl rounded-b-lg flex items-center justify-center transform rotate-15 shadow-2xl border-2 border-white/20">
                  {/* Bottle Cap */}
                  <div className="absolute top-0 w-16 h-4 bg-gradient-to-b from-gray-300 to-gray-400 rounded-t-xl"></div>
                  
                  {/* Bottle SVG */}
                  <svg className="w-16 h-20 text-white/90" fill="currentColor" viewBox="0 0 24 24">
                    <path d="M7 2v2h1v14a4 4 0 004 4h0a4 4 0 004-4V4h1V2H7zm2 2h6v14a2 2 0 01-2 2h0a2 2 0 01-2-2V4z"/>
                    <path d="M9 6h6v2H9z" opacity="0.3"/>
                  </svg>
                  
                  {/* Bottle Shine */}
                  <div className="absolute top-8 left-2 w-2 h-12 bg-white/30 rounded-full blur-sm"></div>
                </div>
                
                {/* Pouring Milk Stream */}
                <div className="absolute top-24 left-1/2 transform -translate-x-1/2 w-3 h-40 bg-gradient-to-b from-white via-white/80 to-white/40 rounded-full animate-pulse shadow-lg">
                  {/* Stream Shine */}
                  <div className="absolute top-0 left-0.5 w-1 h-full bg-white/60 rounded-full"></div>
                </div>
                
                {/* Falling Milk Drops */}
                <div className="absolute top-64 left-1/2 transform -translate-x-1/2">
                  <div className="w-4 h-4 bg-white rounded-full animate-bounce shadow-lg">
                    <div className="w-full h-full bg-white/80 rounded-full animate-ping"></div>
                  </div>
                  <div className="w-3 h-3 bg-white/90 rounded-full animate-bounce animation-delay-1 mt-12 shadow-md"></div>
                  <div className="w-5 h-5 bg-white/70 rounded-full animate-bounce animation-delay-2 mt-24 shadow-lg">
                    <div className="w-full h-full bg-white/50 rounded-full animate-ping"></div>
                  </div>
                  <div className="w-3 h-3 bg-white/80 rounded-full animate-bounce animation-delay-3 mt-36 shadow-md"></div>
                  <div className="w-4 h-4 bg-white/60 rounded-full animate-bounce animation-delay-4 mt-48 shadow-sm"></div>
                  <div className="w-2 h-2 bg-white/90 rounded-full animate-bounce animation-delay-5 mt-60 shadow-md"></div>
                </div>
              </div>
            </div>
            
            {/* Milk Splash at Bottom */}
            <div className="absolute bottom-16 left-1/2 transform -translate-x-1/2 z-10">
              <div className="relative">
                {/* Main Splash Pool */}
                <div className="w-32 h-16 bg-gradient-to-b from-white/40 to-white/20 rounded-full blur-xl animate-pulse shadow-2xl"></div>
                
                {/* Splash Ripple */}
                <div className="absolute top-0 left-1/2 transform -translate-x-1/2 w-24 h-12 bg-white/30 rounded-full blur-lg animate-ping"></div>
                <div className="absolute top-2 left-1/2 transform -translate-x-1/2 w-20 h-10 bg-white/25 rounded-full blur-md animate-ping animation-delay-2"></div>
                
                {/* Splash Drops Flying Up */}
                <div className="absolute -top-8 left-4 w-3 h-3 bg-white/70 rounded-full animate-bounce shadow-md"></div>
                <div className="absolute -top-12 right-6 w-4 h-4 bg-white/60 rounded-full animate-bounce animation-delay-1 shadow-lg"></div>
                <div className="absolute -top-6 left-12 w-2 h-2 bg-white/80 rounded-full animate-bounce animation-delay-2 shadow-sm"></div>
                <div className="absolute -top-10 right-12 w-3 h-3 bg-white/50 rounded-full animate-bounce animation-delay-3 shadow-md"></div>
                <div className="absolute -top-4 left-20 w-2 h-2 bg-white/70 rounded-full animate-bounce animation-delay-4 shadow-sm"></div>
                <div className="absolute -top-14 left-8 w-3 h-3 bg-white/40 rounded-full animate-bounce animation-delay-5 shadow-md"></div>
                <div className="absolute -top-8 right-16 w-2 h-2 bg-white/60 rounded-full animate-bounce animation-delay-6 shadow-sm"></div>
                
                {/* Splash Foam Bubbles */}
                <div className="absolute top-2 left-8 w-2 h-2 bg-white/90 rounded-full animate-pulse"></div>
                <div className="absolute top-4 right-10 w-3 h-3 bg-white/80 rounded-full animate-pulse animation-delay-1"></div>
                <div className="absolute top-6 left-16 w-2 h-2 bg-white/70 rounded-full animate-pulse animation-delay-2"></div>
                <div className="absolute top-3 right-6 w-1 h-1 bg-white/95 rounded-full animate-pulse animation-delay-3"></div>
              </div>
            </div>
          </div>
          
          {/* Animated Gradient Overlay */}
          <div className="absolute inset-0 bg-gradient-to-t from-black/40 via-transparent to-transparent"></div>
        </div>

        {/* Hero Content */}
        <div className="relative z-10 text-center px-4 max-w-6xl mx-auto">
          
          {/* Animated Milk Bottle Logo */}
          <div className="mb-8">
            <div className="inline-block relative">
              <div className="w-24 h-24 relative animate-bounce">
                {/* Glow Effect */}
                <div className="absolute inset-0 bg-white/30 backdrop-blur-xl rounded-3xl animate-pulse"></div>
                
                {/* Main Bottle */}
                <div className="absolute inset-0 bg-white/90 backdrop-blur-xl rounded-3xl flex items-center justify-center transform hover:scale-110 transition-transform duration-500 shadow-2xl">
                  <svg className="w-16 h-16 text-blue-600" fill="currentColor" viewBox="0 0 24 24">
                    <path d="M7 2v2h1v14a4 4 0 004 4h0a4 4 0 004-4V4h1V2H7zm2 2h6v14a2 2 0 01-2 2h0a2 2 0 01-2-2V4z"/>
                    <path d="M9 6h6v2H9z" opacity="0.3"/>
                  </svg>
                </div>
                
                {/* Animated Milk Drops */}
                <div className="absolute -top-2 -right-2 w-4 h-4 bg-blue-400 rounded-full animate-bounce">
                  <div className="w-full h-full bg-blue-500 rounded-full animate-ping"></div>
                </div>
                <div className="absolute -bottom-1 -left-1 w-3 h-3 bg-purple-400 rounded-full animate-pulse"></div>
              </div>
            </div>
          </div>

          {/* Auto-Sliding Text */}
          <div className="mb-8 h-24 overflow-hidden">
            <div className="transition-transform duration-500 ease-in-out" style={{ transform: `translateY(-${currentSlide * 96}px)` }}>
              <div className="h-24 flex items-center justify-center">
                <h1 className="text-4xl md:text-6xl font-bold text-white">
                  Fresh Milk & Dairy Products
                </h1>
              </div>
              <div className="h-24 flex items-center justify-center">
                <h1 className="text-4xl md:text-6xl font-bold text-white">
                  Farm Fresh Quality
                </h1>
              </div>
              <div className="h-24 flex items-center justify-center">
                <h1 className="text-4xl md:text-6xl font-bold text-white">
                  Delivered Daily
                </h1>
              </div>
            </div>
          </div>
          
          <div className="mb-8">
            <p className="text-xl md:text-2xl text-white/90 max-w-2xl mx-auto animate-fade-in">
              Delivering farm-fresh dairy products directly to your doorstep
            </p>
          </div>

          <div className="flex flex-col sm:flex-row gap-4 justify-center mb-12">
            <Link 
              to="/products" 
              className="px-8 py-4 bg-white text-blue-600 rounded-full font-bold text-lg hover:bg-blue-50 transform hover:scale-105 transition-all duration-300 shadow-2xl animate-fade-in animation-delay-2"
            >
              Shop Now
            </Link>
            {!userAuthenticated && (
              <Link 
                to="/register" 
                className="px-8 py-4 border-2 border-white text-white rounded-full font-bold text-lg hover:bg-white hover:text-blue-600 transform hover:scale-105 transition-all duration-300 animate-fade-in animation-delay-4"
              >
                Create Account
              </Link>
            )}
          </div>

          {/* Slide Indicators */}
          <div className="flex justify-center space-x-2">
            {[0, 1, 2].map((index) => (
              <button
                key={index}
                onClick={() => setCurrentSlide(index)}
                className={`w-3 h-3 rounded-full transition-all duration-300 ${
                  currentSlide === index 
                    ? 'bg-white w-8' 
                    : 'bg-white/50 hover:bg-white/70'
                }`}
              />
            ))}
          </div>
        </div>
      </section>

      {/* Categories Section */}
      <section className="mb-12">
        <h2 className={`text-2xl font-bold mb-6 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>Shop by Category</h2>
        <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
          {categories.map((category) => (
            <Link
              key={category}
              to={`/products?category=${category}`}
              className="card p-6 text-center hover:border-primary-500 border-2 border-transparent"
            >
              <div className="text-4xl mb-2">
                {category === 'milk' && '🥛'}
                {category === 'ghee' && '🍯'}
                {category === 'cheese' && '🧀'}
                {category === 'butter' && '🧈'}
                {category === 'curd' && '🥣'}
                {category === 'paneer' && '🧊'}
                {category === 'cream' && '🍦'}
                {category === 'yogurt' && '🍶'}
                {category === 'lassi' && '🥤'}
                {category === 'buttermilk' && '🫙'}
              </div>
              <h3 className={`font-semibold capitalize ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>{category}</h3>
            </Link>
          ))}
        </div>
      </section>

      {/* Featured Products Section */}
      <section className="mb-12">
        <div className="flex items-center justify-between mb-6">
          <h2 className={`text-2xl font-bold ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>Featured Products</h2>
          <Link to="/products" className={`hover:underline ${isDarkMode ? 'text-blue-400 hover:text-blue-300' : 'text-primary-600 hover:text-primary-700'}`}>
            View All →
          </Link>
        </div>
        
        {loading ? (
          <div className="flex justify-center py-12">
            <div className="spinner"></div>
          </div>
        ) : featuredProducts.length > 0 ? (
<div className="product-grid">
            {featuredProducts.slice(0, 8).map((product, index) => (
              <ProductCard key={product._id} product={product} index={index} />
            ))}
          </div>
        ) : (
          <div className="empty-state">
            <div className="empty-state-icon">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-24 w-24" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" />
              </svg>
            </div>
            <h3 className={`text-xl font-semibold mb-2 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>No products yet</h3>
            <p className={`mb-4 ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>Check back soon for fresh dairy products!</p>
            <Link to="/products" className="btn btn-primary">
              Browse Products
            </Link>
          </div>
        )}
      </section>

      {/* Features Section */}
      <section className="mb-12">
        <div className="grid md:grid-cols-3 gap-8">
          <div className="card p-6 text-center">
            <div className="w-16 h-16 bg-primary-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-primary-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
              </svg>
            </div>
            <h3 className={`text-lg font-semibold mb-2 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>Fresh Quality</h3>
            <p className={isDarkMode ? 'text-gray-300' : 'text-gray-600'}>100% pure and fresh dairy products sourced from trusted farms</p>
          </div>
          
          <div className="card p-6 text-center">
            <div className="w-16 h-16 bg-primary-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-primary-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
            </div>
            <h3 className={`text-lg font-semibold mb-2 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>Fast Delivery</h3>
            <p className={isDarkMode ? 'text-gray-300' : 'text-gray-600'}>Quick and reliable delivery to ensure product freshness</p>
          </div>
          
          <div className="card p-6 text-center">
            <div className="w-16 h-16 bg-primary-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-primary-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
